(()=>{
const reduced=matchMedia('(prefers-reduced-motion: reduce)');
if(!reduced.matches)document.documentElement.classList.add('js-motion');
const reveals=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in');reveals.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(e=>reveals.observe(e));
const menu=document.querySelector('.menu-toggle'),nav=document.querySelector('#primary-menu');
function closeMenu(){nav?.classList.remove('open');menu?.setAttribute('aria-expanded','false');if(menu)menu.textContent='Menu'}
menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';nav.classList.toggle('open',open);menu.setAttribute('aria-expanded',String(open));menu.textContent=open?'Close':'Menu'});
nav?.addEventListener('click',e=>{if(e.target.closest('a'))closeMenu()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav?.classList.contains('open')){closeMenu();menu.focus()}});
const header=document.querySelector('header');let pending=false;function scrollUpdate(){pending=false;header?.classList.toggle('scrolled',scrollY>35);if(reduced.matches)return;document.querySelectorAll('.project-story').forEach(el=>{const rect=el.getBoundingClientRect();if(rect.bottom>0&&rect.top<innerHeight){const media=el.querySelector('.project-media');media?.style.setProperty('--media-shift',innerWidth>860?Math.max(-14,Math.min(14,(rect.top-innerHeight*.3)*.025))+'px':'0px')}})}
addEventListener('scroll',()=>{if(!pending){pending=true;requestAnimationFrame(scrollUpdate)}},{passive:true});scrollUpdate();
const panels=[...document.querySelectorAll('.stage-panel')],tabs=[...document.querySelectorAll('[data-stage]')];let active=0,cycle=null,interacted=false;panels.forEach((p,i)=>{p.hidden=false;p.inert=i!==0;p.setAttribute('aria-hidden',String(i!==0))});
async function show(index,manual=false){if(!panels[index])return;const targetImage=panels[index].querySelector("img");if(targetImage&&!targetImage.complete){try{await targetImage.decode()}catch{return}}const old=panels[active];active=index;document.querySelector(".hero-stage").dataset.active=String(index);panels.forEach((p,i)=>{p.inert=i!==index;p.setAttribute('aria-hidden',String(i!==index));p.classList.toggle('active',i===index)});tabs.forEach((b,i)=>{b.classList.toggle('selected',i===index);b.setAttribute('aria-pressed',String(i===index))});document.querySelector('.stage-caption').textContent=panels[index].dataset.label;document.querySelector('#stage-count').textContent=String(index+1).padStart(2,'0')+' / '+String(panels.length).padStart(2,'0');panels.forEach((p,i)=>p.querySelectorAll('video').forEach(v=>{if(i!==index)v.pause();else if(!reduced.matches)v.play().catch(()=>{})}));if(manual){interacted=true;clearInterval(cycle)}if(panels[index].querySelector('.automation-demo')&&!reduced.matches)runDemo(panels[index].querySelector('.automation-demo'));}
tabs.forEach(b=>b.addEventListener('click',()=>show(Number(b.dataset.stage),true)));
// Rotation stops when a visitor interacts, focuses or pauses it; every panel is populated in initial HTML.
const stage=document.querySelector('.hero-stage');let stageVisible=true;
if(stage){new IntersectionObserver(es=>{stageVisible=es[0].isIntersecting},{threshold:.1}).observe(stage);stage.addEventListener('focusin',()=>{interacted=true;clearInterval(cycle)});stage.addEventListener('pointerenter',()=>{interacted=true;clearInterval(cycle)});if(!reduced.matches)cycle=setInterval(()=>{if(!interacted&&stageVisible&&!document.hidden)show((active+1)%panels.length)},6000)}
document.querySelector('[data-pause-stage]')?.addEventListener('click',e=>{interacted=true;clearInterval(cycle);e.currentTarget.textContent='Rotation paused';e.currentTarget.disabled=true});
const tilt=document.querySelector('[data-tilt]');if(tilt&&matchMedia('(hover:hover) and (pointer:fine)').matches&&!reduced.matches){tilt.addEventListener('pointermove',e=>{const r=tilt.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;tilt.style.transform=`rotateY(${x*7}deg) rotateX(${-y*5}deg)`});tilt.addEventListener('pointerleave',()=>tilt.style.transform='')}
const dialog=document.querySelector('#media-dialog');let lastZoom=null;document.querySelectorAll('.zoom-media').forEach(b=>b.addEventListener('click',()=>{lastZoom=b;dialog.querySelector('img').src=b.dataset.image;dialog.querySelector('img').alt=b.dataset.caption;dialog.querySelector('p').textContent=b.dataset.caption;dialog.showModal()}));dialog?.addEventListener('close',()=>lastZoom?.focus());dialog?.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});
// Pause films outside the viewport. Native controls remain available on touch and with reduced motion.
const videos=[...document.querySelectorAll('video')];const videoObserver=new IntersectionObserver(entries=>entries.forEach(({target:v,isIntersecting})=>{if(!isIntersecting||v.closest('.stage-panel:not(.active)')){v.pause();return}if(!reduced.matches&&!document.hidden&&!v.dataset.userPaused)v.play().catch(()=>{})}),{threshold:.3});videos.forEach(v=>{v.muted=true;videoObserver.observe(v);v.addEventListener('pointerdown',()=>{v.dataset.userPaused='true'})});
document.addEventListener('visibilitychange',()=>{if(document.hidden)videos.forEach(v=>v.pause())});
const demoTimers=new WeakMap();
function runDemo(demo){(demoTimers.get(demo)||[]).forEach(clearTimeout);const steps=[...demo.querySelectorAll('.flow-node')],output=demo.querySelector('.demo-output'),button=demo.querySelector('[data-run-demo]');steps.forEach(s=>s.classList.remove('active','done'));const lines=['Reading the sample project inquiry…','Classified: website redesign. Routing to the digital team…','Draft prepared. A person reviews the response before sending.'];const timers=[];steps.forEach((s,i)=>{timers.push(setTimeout(()=>{steps.forEach((x,j)=>{x.classList.toggle('done',j<i);x.classList.toggle('active',j===i)});output.textContent=lines[i];button.textContent=i===2?'Replay example':'Running example';},reduced.matches?0:i*1400))});demoTimers.set(demo,timers)}
document.querySelectorAll('[data-run-demo]').forEach(b=>b.addEventListener('click',()=>runDemo(b.closest('.automation-demo'))));
reduced.addEventListener('change',()=>{if(reduced.matches){clearInterval(cycle);videos.forEach(v=>v.pause());document.documentElement.classList.remove('js-motion');if(tilt)tilt.style.transform=''}});
function track(event,detail={}){window.dataLayer=window.dataLayer||[];window.dataLayer.push({event,...detail})}document.querySelectorAll('a[href^="https://wa.me/"]').forEach(a=>a.addEventListener('click',()=>track('whatsapp_click')));document.querySelectorAll('a[href^="tel:"]').forEach(a=>a.addEventListener('click',()=>track('phone_click')));document.querySelectorAll('a[href^="mailto:"]').forEach(a=>a.addEventListener('click',()=>track('email_click')));
const form=document.querySelector('#projectForm');if(form){const project=new URLSearchParams(location.search).get('project');if(project==='Address12')form.elements.project.value='Address12 demonstration';form.addEventListener('focusin',()=>track('project_form_start'),{once:true});form.addEventListener('submit',async e=>{e.preventDefault();if(form.elements.website.value)return;if(form.dataset.backend==='netlify'){const button=form.querySelector('[type=submit]'),status=document.querySelector('#form-status');if(button.disabled)return;button.disabled=true;button.textContent='Sending…';status.textContent='Sending your project inquiry…';try{const response=await fetch('/',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams(new FormData(form)).toString()});if(!response.ok)throw Error('Submission failed');status.textContent='Your inquiry has been received. Thank you for sharing your project.';form.reset();track('project_form_submit')}catch{status.textContent='Your inquiry could not be sent. Please try again or email visioncraftlabs@gmail.com.'}finally{button.disabled=false;button.textContent='Send project inquiry'}return}const values=new FormData(form),brief=['Project inquiry — VisionCraft Labs','',...['name','company','email','phone','project','budget','timeline','description'].map(k=>k[0].toUpperCase()+k.slice(1)+': '+(values.get(k)||'Not specified'))].join('\n');document.querySelector('#email-draft').value=brief;document.querySelector('#draft-actions').hidden=false;document.querySelector('#form-status').textContent='Your brief is ready. Send it from your mail app, or copy it below. Nothing has been sent yet.';track('project_brief_prepare');location.href='mailto:visioncraftlabs@gmail.com?subject='+encodeURIComponent('Project inquiry: '+values.get('project'))+'&body='+encodeURIComponent(brief)});document.querySelector('#copy-brief').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(document.querySelector('#email-draft').value);document.querySelector('#form-status').textContent='Brief copied. Paste it into an email to visioncraftlabs@gmail.com.'}catch{document.querySelector('#email-draft').select();document.querySelector('#form-status').textContent='Select and copy the prepared brief below.'}})}
})();
